def transform_v14(grid):
    if not grid:
        return grid

    h, w = len(grid), len(grid[0])

    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    if not ones:
        return grid

    min_r, max_r = min(r for r, c in ones), max(r for r, c in ones)
    min_c, max_c = min(c for r, c in ones), max(c for r, c in ones)

    result = [[0]*w for _ in range(h)]

    for r in range(h):
        cols_with_1s = [c for c in range(w) if grid[r][c] == 1]
        if not cols_with_1s:
            continue

        min_col_1, max_col_1 = cols_with_1s[0], cols_with_1s[-1]

        # Left 2s for ALL rows
        for c in range(min_col_1):
            result[r][c] = 2

        # Right 2s
        for c in range(max_col_1 + 1, max_c + 2):
            if c < w:
                result[r][c] = 2

        # Place 1s
        for c in range(w):
            if grid[r][c] == 1:
                result[r][c] = 1

    # Fill interior with 3s
    for r in range(min_r + 1, max_r + 1):
        for c in range(min_c + 1, max_c):
            if result[r][c] not in [1, 2]:
                result[r][c] = 3

    # Bottom closure row: if row max_r + 1 has no 1s, fill rows min_col_1 to max_c + 1 as 2s
    r_bottom = max_r + 1
    if r_bottom < h:
        cols_with_1s = [c for c in range(w) if grid[r_bottom][c] == 1]
        if not cols_with_1s:
            # Fill 2s from col 0 to max_c + 1
            for c in range(max_c + 2):
                if c < w:
                    result[r_bottom][c] = 2

    return result

